export const styles="\n:host{color-scheme:light;--ink:#181b22;--muted:#707785;--line:#dce1e8;--surface:#fff;--soft:#f3f5f7;--accent:#e72b3b;--accent2:#ff6470;--shadow:0 22px 70px rgba(28,34,45,.12)}\n*{box-sizing:border-box}.mockup-body{margin:0;min-height:100%;font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Display\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif;color:var(--ink);background:#eef1f4}.mockup-body{padding:0}.shell{max-width:1520px;margin:0 auto}.topbar{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:2px 6px 22px}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(135deg,#141820,#5c6573);color:#fff;font-weight:700}.brand h1{font-size:18px;letter-spacing:.02em;margin:0}.brand p{margin:3px 0 0;color:var(--muted);font-size:12px}.local-pill{font-size:12px;color:#4f7a5e;background:#e7f3e9;border:1px solid #c8e1cc;padding:8px 12px;border-radius:999px}.notice{margin:0 0 18px;padding:12px 16px;border-radius:12px;border:1px solid #f0c79e;background:#fff7ed;color:#7f5426;font-size:12px;line-height:1.7}.notice b{color:#52351b}.app{display:grid;grid-template-columns:300px minmax(0,1fr);gap:18px}.panel{background:rgba(255,255,255,.88);border:1px solid rgba(211,218,227,.9);box-shadow:var(--shadow);border-radius:22px}.controls{padding:22px}.kicker{font-size:11px;letter-spacing:.18em;color:#9aa2ad;margin-bottom:8px}.controls h2,.viewer h2{font-size:18px;margin:0 0 6px}.sub{font-size:12px;color:var(--muted);line-height:1.7;margin:0 0 18px}.upload{display:grid;place-items:center;gap:7px;min-height:158px;border:1.5px dashed #d0d7df;border-radius:16px;background:#fafbfc;cursor:pointer;text-align:center;transition:.2s}.upload:hover,.upload.dragging{border-color:var(--accent);background:#fff7f8}.upload strong{font-size:14px}.upload small{font-size:11px;color:var(--muted)}.upload-plus{font-size:35px;line-height:1;color:var(--accent);font-weight:200}.field{display:grid;gap:7px;margin-top:15px;font-size:12px;color:var(--muted)}select,.file-button{height:40px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--ink);padding:0 11px;font:inherit}.file-button{display:flex;align-items:center;justify-content:center;cursor:pointer;color:#4c5561}.switch-row{display:flex;gap:9px;align-items:center;margin-top:15px;font-size:12px;color:var(--muted)}.switch-row input{accent-color:var(--accent)}.actions{display:grid;gap:9px;margin-top:18px}.primary,.secondary{height:42px;border-radius:11px;border:0;font:600 13px inherit;cursor:pointer}.primary{background:linear-gradient(120deg,#d91528,#ff5360);color:#fff;box-shadow:0 10px 24px rgba(221,27,45,.22)}.secondary{border:1px solid var(--line);background:#fff;color:#525a65}.primary:disabled{opacity:.45;cursor:not-allowed}.status{min-height:38px;font-size:11px;color:var(--muted);line-height:1.7;margin:13px 0 0}.model-info{margin-top:18px;padding-top:16px;border-top:1px solid var(--line);font-size:11px;line-height:1.8;color:var(--muted)}.model-info strong{color:var(--ink)}.viewer{padding:0;overflow:hidden}.viewer-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px 24px;border-bottom:1px solid var(--line)}.viewer-head .meta{text-align:right;color:var(--muted);font-size:11px;line-height:1.6}.type-tabs{display:flex;gap:8px;flex-wrap:wrap;padding:16px 24px;border-bottom:1px solid var(--line)}.type-tabs button{border:1px solid var(--line);border-radius:999px;background:#fff;padding:9px 13px;color:#626b77;font:600 12px inherit;cursor:pointer}.type-tabs button[aria-selected=true]{color:#fff;border-color:var(--accent);background:var(--accent);box-shadow:0 7px 16px rgba(231,43,59,.2)}.stage-wrap{position:relative;min-height:680px;background:linear-gradient(160deg,#f9fafb,#e8edf1);overflow:hidden}.stage-wrap:before{content:\"\";position:absolute;inset:0;background-image:linear-gradient(rgba(130,143,158,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(130,143,158,.08) 1px,transparent 1px);background-size:28px 28px;mask-image:linear-gradient(to bottom,rgba(0,0,0,.5),transparent)}canvas{display:block;width:100%;height:680px;position:relative;z-index:1;touch-action:none}.stage-tip{position:absolute;z-index:2;left:22px;bottom:18px;padding:8px 11px;border-radius:999px;background:rgba(255,255,255,.76);border:1px solid rgba(210,218,225,.86);color:#67717f;font-size:11px;pointer-events:none}.loading{position:absolute;z-index:4;inset:0;display:grid;place-items:center;background:rgba(242,245,248,.8);color:#606a77;font-size:12px}.loading[hidden]{display:none}.footer-note{padding:16px 24px;color:#89919c;font-size:11px;line-height:1.8;border-top:1px solid var(--line)}.footer-note a{color:inherit}.gltf-note{margin-top:12px;padding:10px 11px;border-radius:10px;background:#f4f6f8;color:#76808b;font-size:10px;line-height:1.7}@media(max-width:900px){body{padding:12px}.app{grid-template-columns:1fr}.controls{order:2}.viewer{order:1}.stage-wrap,canvas{height:560px;min-height:560px}.viewer-head{padding:18px}.type-tabs{padding:13px 18px}}@media(max-width:520px){.topbar{align-items:flex-start;flex-direction:column;gap:10px}.local-pill{align-self:flex-start}.stage-wrap,canvas{height:470px;min-height:470px}.controls{padding:16px}}\n\n[hidden]{display:none!important}.slot-list{display:grid;gap:10px}.slot-upload{display:flex;gap:12px;align-items:center;border:1px dashed #cdd5df;border-radius:13px;padding:14px 12px;cursor:pointer;background:#fafbfc}.slot-upload:hover{border-color:var(--accent);background:#fff7f8}.slot-icon{display:grid;place-items:center;width:33px;height:38px;color:var(--accent);background:#fceef0;border-radius:8px;font-size:11px;font-weight:700}.slot-upload strong{display:block;font-size:13px}.slot-upload small{display:block;font-size:10px;color:var(--muted);line-height:1.7;max-width:188px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.view-tabs{display:flex;flex-wrap:wrap;gap:5px;padding:10px 22px;border-bottom:1px solid var(--line);background:#fbfcfd}.view-tabs button{padding:7px 10px;border:0;border-radius:7px;background:transparent;color:#7a838f;cursor:pointer}.view-tabs button[aria-pressed=true]{background:#e8ecf1;color:#232b36}.primary,.secondary{font-family:inherit;font-size:13px;font-weight:600}.text-action{height:30px;font-weight:400;border:0;background:transparent;font-size:11px}.file-button{width:100%;font-family:inherit;font-size:11px;margin-top:9px}.stage-wrap{height:610px;min-height:610px}canvas{height:100%;width:100%}#threeLabels{position:absolute;left:0;right:0;top:16px;display:grid;grid-template-columns:repeat(3,1fr);font-size:11px;text-align:center;color:#66717d;z-index:2;pointer-events:none}#savePreview{max-width:100%;display:block;margin-top:8px}#saveFallback{font-size:11px;color:var(--muted)}#saveLink{color:var(--accent)}#logoScale{accent-color:var(--accent);width:100%}.status{overflow-wrap:anywhere}.stage-tip{pointer-events:none}.loading{padding:28px;text-align:center;line-height:1.9}.loading a{color:var(--accent)}@media(max-width:900px){.stage-wrap{height:520px;min-height:520px}.controls{order:0}.viewer{order:1}.app{grid-template-columns:minmax(230px,280px) minmax(0,1fr)}}@media(max-width:680px){.app{grid-template-columns:1fr}.stage-wrap{height:460px;min-height:460px}.type-tabs{gap:5px}.type-tabs button{padding:7px 10px}.view-tabs{padding:9px 12px}.controls{padding:18px}.upload{min-height:112px}}\n.color-controls{margin-top:17px;border-top:1px solid var(--line);padding-top:2px}.color-field{display:flex;align-items:center;justify-content:space-between;font-size:11px;color:var(--muted);margin-top:12px}.color-field output{color:var(--ink);font-variant-numeric:tabular-nums}.color-controls input[type=range]{width:100%;accent-color:var(--accent);height:17px;margin:6px 0 0}.color-note{font-size:10px;line-height:1.7;color:var(--muted);margin:8px 0!important}.controls{align-self:start}.viewer{position:sticky;top:16px;align-self:start}.stage-wrap{min-height:450px;height:clamp(450px,68vh,660px)}canvas{min-height:0!important}@media(max-width:680px){.viewer{position:static}.stage-wrap{height:460px;min-height:460px}}\n#photoCanvas{touch-action:auto} .view-tabs button:disabled{opacity:.45;cursor:default}\n\n:host{display:block;min-width:0;color-scheme:inherit;--ink:var(--text-main,#20232b);--muted:var(--text-muted,#858a96);--line:var(--border-color,#343640);--surface:var(--bg-panel,#18191e);--soft:var(--bg-inner,#202127);--accent:var(--accent-red,#ed1728);--shadow:var(--ui-panel-shadow,none)}\n.mockup-body{padding:0;background:transparent;color:var(--ink);font-family:inherit;min-height:0}.shell{max-width:none;margin:0}.topbar{display:none}\n.panel{background:var(--surface);border-color:var(--line);box-shadow:var(--shadow)}.controls{padding:22px}.viewer{top:12px}.viewer-head,.type-tabs,.view-tabs,.footer-note{border-color:var(--line)}\n.view-tabs,.footer-note{background:var(--surface)}select,.file-button,.secondary,.type-tabs button{color:var(--ink);background:var(--bg-input,#202127);border-color:var(--line)}\n.upload,.slot-upload{background:var(--bg-input,#202127);border-color:var(--border-highlight,#454752)}.upload:hover,.upload.dragging,.slot-upload:hover{background:var(--bg-inner,#272830);border-color:var(--accent)}\n.type-tabs button[aria-selected=true]{background:var(--accent);color:white;border-color:var(--accent)}.view-tabs button[aria-pressed=true]{background:var(--bg-inner,#30313a);color:var(--ink)}.slot-icon{background:var(--bg-inner,#272830)}\n.stage-wrap{background:#e9edf1}.stage-tip{color:#67717f}.gltf-note{background:var(--bg-inner,#202127);color:var(--muted)}.file-button,.primary,.secondary,select,button{font-family:inherit}.notice{font-size:12px}.text-action{color:var(--muted)}\n@media(max-width:680px){.controls{padding:18px}.app{grid-template-columns:1fr}.viewer{position:static}}\n";
export const markup="<div class=\"mockup-body\"><div class=\"shell\">\n  <header class=\"topbar\"><div class=\"brand\"><div class=\"brand-mark\">3D</div><div><h1>3D 样机生成器</h1><p>优悦教育 · 3D 样机与照片式穿着 / V5</p></div></div><span class=\"local-pill\">图片只在本机处理</span></header>\n  <div class=\"notice\" id=\"protocolNotice\" hidden>当前通过本地文件打开；若模型未出现，请使用包内的“启动预览.command”。首次打开需要联网加载 Three.js。</div>\n  <main class=\"app\">\n    <aside class=\"panel controls\">\n      <div class=\"kicker\">01 · ARTWORK</div><h2 id=\"uploadTitle\">上传设计画面</h2><p class=\"sub\" id=\"uploadHint\">图片贴合在实体表面，可旋转查看。</p>\n      <div id=\"mainUpload\">\n        <label class=\"upload\" id=\"uploadBox\" for=\"artInput\"><span class=\"upload-plus\">＋</span><strong>选择图片</strong><small id=\"mainFileName\">PNG · JPG · WebP</small><input id=\"artInput\" data-slot=\"main\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label>\n      </div>\n      <div id=\"bookUploads\" class=\"slot-list\" hidden>\n        <label class=\"slot-upload\"><span class=\"slot-icon\">01</span><span><strong>书本封面</strong><small id=\"bookFrontName\">选择正面封面</small></span><input data-slot=\"bookFront\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label>\n        <label class=\"slot-upload\"><span class=\"slot-icon\">02</span><span><strong>书本封底</strong><small id=\"bookBackName\">选择背面封底</small></span><input data-slot=\"bookBack\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label>\n        <label class=\"slot-upload\"><span class=\"slot-icon\">03</span><span><strong>书脊（单边）</strong><small id=\"bookSpineName\">仅左侧书脊 · 右侧保留纸张</small></span><input data-slot=\"bookSpine\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label>\n      </div>\n      <div id=\"bagUploads\" class=\"slot-list\" hidden>\n        <label class=\"slot-upload\"><span class=\"slot-icon\">01</span><span><strong>袋子正面</strong><small id=\"bagFrontName\">选择正面设计</small></span><input data-slot=\"bagFront\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label>\n        <label class=\"slot-upload\"><span class=\"slot-icon\">02</span><span><strong>袋子背面</strong><small id=\"bagBackName\">选择背面设计</small></span><input data-slot=\"bagBack\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label>\n        <label class=\"slot-upload\"><span class=\"slot-icon\">03</span><span><strong>袋子两侧</strong><small id=\"bagSideName\">同一图片用于左、右两侧</small></span><input data-slot=\"bagSide\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label>\n      </div>\n      <div id=\"shirtUpload\" hidden>\n        <label class=\"upload\" for=\"logoInput\"><span class=\"upload-plus\">＋</span><strong>上传胸前小 Logo</strong><small id=\"shirtLogoName\">推荐透明 PNG · 仅上胸小区域</small><input id=\"logoInput\" data-slot=\"shirtLogo\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label>\n      </div>\n      <label class=\"field\">样机类型<select id=\"modelType\"><option value=\"booklet\">画册 / 书本</option><option value=\"a4\">A4 纸张</option><option value=\"banner\">易拉宝 · 80 × 180</option><option value=\"bag\">手提袋 · 三面设计</option><option value=\"phone\">圆角全面屏手机</option><option value=\"shirt\">T 恤 · 照片式穿着</option></select></label>\n      <label class=\"field\" id=\"fitField\">图片适配<select id=\"fitMode\"><option value=\"cover\">等比裁切铺满</option><option value=\"contain\">完整显示（保留留白）</option></select></label>\n      <section class=\"color-controls\" aria-label=\"画面颜色调整\">\n        <label class=\"field\" id=\"colorModeField\">色彩模式<select id=\"colorMode\"><option value=\"faithful\">原图优先（推荐）</option><option value=\"studio\">摄影棚效果</option></select></label>\n        <p class=\"color-note\" id=\"colorModeNote\">保留原图色彩，减轻灯光造成的偏亮与褪色。</p>\n        <label class=\"color-field\" for=\"artBrightness\">画面亮度 <output id=\"artBrightnessValue\">100%</output></label><input id=\"artBrightness\" type=\"range\" min=\"50\" max=\"150\" step=\"1\" value=\"100\">\n        <label class=\"color-field\" for=\"artContrast\">对比度 <output id=\"artContrastValue\">100%</output></label><input id=\"artContrast\" type=\"range\" min=\"50\" max=\"150\" step=\"1\" value=\"100\">\n        <label class=\"color-field\" for=\"artSaturation\">饱和度 <output id=\"artSaturationValue\">100%</output></label><input id=\"artSaturation\" type=\"range\" min=\"0\" max=\"170\" step=\"1\" value=\"100\">\n        <button class=\"secondary text-action\" id=\"resetColorBtn\" type=\"button\">恢复推荐色彩</button>\n      </section>\n      \n      <div id=\"logoSettings\" hidden><label class=\"field\">Logo 大小 <input id=\"logoScale\" type=\"range\" min=\"50\" max=\"130\" value=\"100\"></label><label class=\"field\">Logo 左右位置<input id=\"logoX\" type=\"range\" min=\"-80\" max=\"80\" value=\"0\"></label><label class=\"field\">Logo 上下位置<input id=\"logoY\" type=\"range\" min=\"-60\" max=\"100\" value=\"0\"></label></div>\n      <div id=\"customBagControls\" hidden><button type=\"button\" class=\"file-button\" id=\"loadBagBtn\">加载同目录 bag.gltf</button><label class=\"file-button\" for=\"gltfInput\">选择自定义 .glb 模型</label><input id=\"gltfInput\" type=\"file\" accept=\".glb\" hidden></div>\n      <label class=\"switch-row\" id=\"autoRotateRow\"><input id=\"autoRotate\" type=\"checkbox\">自动旋转预览</label>\n      <div class=\"actions\"><button class=\"primary\" id=\"exportBtn\" type=\"button\" disabled>导出当前 3D 画面 PNG</button><button class=\"secondary\" id=\"resetBtn\" type=\"button\">恢复默认视角</button><button class=\"secondary text-action\" id=\"clearBtn\" type=\"button\">清空当前样机图片</button></div>\n      <p id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\">正在准备 3D 场景…</p>\n      <details id=\"saveFallback\" hidden><summary>查看导出图片</summary><a id=\"saveLink\" download>保存 PNG</a><img id=\"savePreview\" alt=\"导出的 3D 样机画面\"></details>\n      <div class=\"model-info\"><strong id=\"modelLabel\">画册 / 书本</strong><br><span id=\"modelDetails\">正面贴图 · 可 360°旋转</span></div>\n    </aside>\n    <section class=\"panel viewer\"><div class=\"viewer-head\"><div><div class=\"kicker\" id=\"previewKicker\">02 · PREVIEW</div><h2 id=\"previewTitle\">真实 3D 预览</h2></div><div class=\"meta\"><span id=\"sizeMeta\">—</span><br><span id=\"renderMeta\">OrbitControls · PBR 材质 · 阴影</span></div></div><div class=\"type-tabs\" role=\"tablist\" aria-label=\"样机类型\"><button type=\"button\" data-type=\"booklet\" aria-selected=\"true\">画册</button><button type=\"button\" data-type=\"a4\" aria-selected=\"false\">A4</button><button type=\"button\" data-type=\"banner\" aria-selected=\"false\">易拉宝</button><button type=\"button\" data-type=\"bag\" aria-selected=\"false\">手提袋</button><button type=\"button\" data-type=\"phone\" aria-selected=\"false\">手机</button><button type=\"button\" data-type=\"shirt\" aria-selected=\"false\">T 恤</button></div><div class=\"view-tabs\" aria-label=\"观察角度\"><button data-view=\"free\" aria-pressed=\"true\">自由旋转</button><button data-view=\"front\" aria-pressed=\"false\">正面</button><button data-view=\"back\" aria-pressed=\"false\">背面</button><button data-view=\"left\" aria-pressed=\"false\">左侧</button><button data-view=\"right\" aria-pressed=\"false\">右侧</button><button data-view=\"three\" aria-pressed=\"false\">三视图</button></div><div class=\"stage-wrap\" id=\"stageWrap\"><div class=\"loading\" id=\"loading\">正在加载 Three.js 场景…</div><canvas id=\"sceneCanvas\" aria-label=\"3D 交互预览\"></canvas><canvas id=\"photoCanvas\" aria-label=\"T恤照片式穿着效果\" hidden></canvas><div id=\"threeLabels\" hidden><span id=\"frontViewLabel\">正面</span><span id=\"sideViewLabel\">右侧</span><span id=\"backViewLabel\">背面</span></div><div class=\"stage-tip\" id=\"stageTip\">拖动旋转 · 滚轮缩放 · 右键平移</div></div><div class=\"footer-note\">T 恤为照片式固定视角；其他样机为 Three.js 3D 预览 · 图片本机处理 · 独立测试版 2026.11.14。<a href=\"https://github.com/mrdoob/three.js\" target=\"_blank\" rel=\"noreferrer\">Three.js · MIT</a></div></section>\n  </main>\n</div></div>";
